            // Index register
            this.I = 0;

            // Program counter
            this.PC = 0x200;

            // Stack
            this.stack = [];
            this.SP = 0;

            // Timers (60 Hz)
            this.delayTimer = 0;
            this.soundTimer = 0;

            // Display (64x32)
            this.display = new Uint8Array(64 * 32);

            // Keypad (4x4)
            this.keys = new Uint8Array(16);

            // Font set (5x8 characters)
