                0xF0, 0x90, 0x90, 0x90, 0xF0, // 0
                0x20, 0x60, 0x20, 0x20, 0x70, // 1
                0xF0, 0x10, 0xF0, 0x80, 0xF0, // 2
                0xF0, 0x10, 0xF0, 0x10, 0xF0, // 3
                0x90, 0x90, 0xF0, 0x10, 0x10, // 4
                0xF0, 0x80, 0xF0, 0x10, 0xF0, // 5
                0xF0, 0x80, 0xF0, 0x90, 0xF0, // 6
                0xF0, 0x10, 0x20, 0x40, 0x40, // 7
                0xF0, 0x90, 0xF0, 0x90, 0xF0, // 8
                0xF0, 0x90, 0xF0, 0x10, 0xF0, // 9
                0xF0, 0x90, 0xF0, 0x90, 0x90, // A
                0xE0, 0x90, 0xE0, 0x90, 0xE0, // B
                0xF0, 0x80, 0x80, 0x80, 0xF0, // C
                0xE0, 0x90, 0x90, 0x90, 0xE0, // D
                0xF0, 0x80, 0xF0, 0x80, 0xF0, // E
                0xF0, 0x80, 0xF0, 0x80, 0x80  // F
            ];

            this.init();
        }

        init() {
            // Clear memory
            this.memory.fill(0);

            // Load font set at 0x050
            for (let i = 0; i < this.fontSet.length; i++) {
                this.memory[0x050 + i] = this.fontSet[i];
            }

            // Reset registers
            this.V.fill(0);

            // Reset index
            this.I = 0;

            // Reset PC
            this.PC = 0x200;

            // Reset stack
            this.stack = [];
            this.SP = 0;

            // Reset timers
            this.delayTimer = 0;
            this.soundTimer = 0;

            // Clear display
            this.display.fill(0);

            // Clear keys
            this.keys.fill(0);
        }

        loadROM(bytes) {
            // Copy ROM to memory starting at 0x200
            for (let i = 0; i < bytes.length; i++) {
                this.memory[0x200 + i] = bytes[i];
            }

            this.reset();
        }

        reset() {
            this.init();
        }

        // Timer updates (60 Hz)
        updateTimers() {
            if (this.delayTimer > 0) {
                this.delayTimer--;
            }
            if (this.soundTimer > 0) {
                this.soundTimer--;
            }
        }

        // Key handling
        setKey(key, pressed) {
            if (key >= 0 && key < 16) {
                this.keys[key] = pressed ? 1 : 0;
            }
        }

        // Draw sprite using XOR with collision flag
        drawSprite(x, y, sprite, n) {
            let collision = 0;
            for (let row = 0; row < n; row++) {
                let spriteByte = sprite[row];
                for (let col = 0; col < 8; col++) {
                    let pixelX = (x + col) % 64;
                    let pixelY = (y + row) % 32;
                    let pixelIndex = pixelY * 64 + pixelX;

                    if ((spriteByte & (0x80 >> col)) !== 0) {
                        if (this.display[pixelIndex] === 1) {
                            collision = 1;
                        }
                        this.display[pixelIndex] ^= 1;
                    }
                }
            }
            this.V[0xF] = collision;
        }

        // Execute one instruction
        step() {
            // Fetch opcode
            let opcode = (this.memory[this.PC] << 8) | this.memory[this.PC + 1];
            this.PC += 2;

            // Decode and execute
            const nnn = opcode & 0x0FFF;
            const nn = opcode & 0x00FF;
            const n = opcode & 0x000F;
            const x = (opcode >> 8) & 0x0F;
            const y = (opcode >> 4) & 0x0F;

            // Clear debug info
            this.debugOpcode = opcode;
            this.debugX = x;
            this.debugY = y;
            this.debugNNN = nnn;
            this.debugNN = nn;
            this.debugN = n;

            switch (opcode & 0xF000) {
                case 0x0000:
                    switch (nn) {
                        case 0x0E0: // CLS
                            this.display.fill(0);
                            break;
                        case 0xEE: // RET
                            this.SP--;
                            this.PC = this.stack[this.SP];
                            break;
                        default:
                            console.warn('Unknown opcode: 0x00' + nn.toString(16));
