                    break;

                case 0x1000: // JP addr
                    this.PC = nnn;
                    break;

                case 0x2000: // CALL addr
                    if (this.SP < 16) {
                        this.stack[this.SP] = this.PC;
                        this.SP++;
                        this.PC = nnn;
                    }
                    break;

                case 0x3000: // SE Vx, byte
                    if (this.V[x] === nn) {
                        this.PC += 2;
                    }
                    break;

                case 0x4000: // SNE Vx, byte
                    if (this.V[x] !== nn) {
                        this.PC += 2;
                    }
                    break;

                case 0x5000: // SE Vx, Vy
                    if (this.V[x] === this.V[y]) {
                        this.PC += 2;
                    }
                    break;

                case 0x6000: // LD Vx, byte
                    this.V[x] = nn;
                    break;

                case 0x7000: // ADD Vx, byte
                    this.V[x] = (this.V[x] + nn) & 0xFF;
                    break;

                case 0x8000:
                    switch (n) {
                        case 0x0: // LD Vx, Vy
                            this.V[x] = this.V[y];
                            break;
                        case 0x1: // OR Vx, Vy
                            this.V[x] |= this.V[y];
                            this.V[0xF] = 0;
                            break;
                        case 0x2: // AND Vx, Vy
                            this.V[x] &= this.V[y];
                            this.V[0xF] = 0;
                            break;
                        case 0x3: // XOR Vx, Vy
                            this.V[x] ^= this.V[y];
                            this.V[0xF] = 0;
                            break;
                        case 0x4: // ADD Vx, Vy
                            let sum = this.V[x] + this.V[y];
                            this.V[0xF] = sum > 0xFF ? 1 : 0;
                            this.V[x] = sum & 0xFF;
                            break;
                        case 0x5: // SUB Vx, Vy
                            this.V[0xF] = this.V[x] > this.V[y] ? 1 : 0;
                            this.V[x] = (this.V[x] - this.V[y]) & 0xFF;
                            break;
                        case 0x6: // SHR Vx
                            this.V[0xF] = this.V[x] & 0x1;
                            this.V[x] >>= 1;
                            break;
                        case 0x7: // SUBN Vx, Vy
                            this.V[0xF] = this.V[y] > this.V[x] ? 1 : 0;
                            this.V[x] = (this.V[y] - this.V[x]) & 0xFF;
                            break;
                        case 0xE: // SHL Vx
                            this.V[0xF] = this.V[x] >> 7;
                            this.V[x] <<= 1;
                            break;
