                case 0x9000: // SNE Vx, Vy
                    if (this.V[x] !== this.V[y]) {
                        this.PC += 2;
                    }
                    break;

                case 0xA000: // LD I, addr
                    this.I = nnn;
                    break;

                case 0xB000: // JP V0, addr
                    this.PC = nnn + this.V[0];
                    break;

                case 0xC000: // RND Vx, byte
                    this.V[x] = Math.floor(Math.random() * 256) & nn;
                    break;

                case 0xD000: // DRW Vx, Vy, nibble
                    let spriteStart = this.I;
                    let sprite = [];
                    for (let i = 0; i < n; i++) {
                        sprite.push(this.memory[spriteStart + i]);
                    }
                    this.drawSprite(this.V[x], this.V[y], sprite, n);
                    break;

                case 0xE000:
                    switch (nn) {
                        case 0x9E: // SKP Vx
                            if (this.keys[this.V[x]]) {
                                this.PC += 2;
                            }
                            break;
                        case 0xA1: // SKNP Vx
                            if (!this.keys[this.V[x]]) {
                                this.PC += 2;
                            }
                            break;
                    }
                    break;

                case 0xF000:
                    switch (nn) {
                        case 0x07: // LD Vx, DT
                            this.V[x] = this.delayTimer;
                            break;
                        case 0x0A: // LD Vx, K
                            // Wait for key press
                            break;
                        case 0x15: // LD DT, Vx
                            this.delayTimer = this.V[x];
                            break;
                        case 0x18: // LD ST, Vx
                            this.soundTimer = this.V[x];
                            break;
                        case 0x1E: // ADD I, Vx
                            if (this.I + this.V[x] <= 0xFFF) {
                                this.I += this.V[x];
                            }
                            break;
                        case 0x29: // LD F, Vx
                            this.I = (this.V[x] & 0xF) * 5;
                            break;
                        case 0x33: // LD B, Vx
                            this.memory[this.I] = Math.floor(this.V[x] / 100);
                            this.memory[this.I + 1] = Math.floor((this.V[x] % 100) / 10);
                            this.memory[this.I + 2] = this.V[x] % 10;
                            break;
                        case 0x55: // LD [I], Vx
                            for (let i = 0; i <= x; i++) {
                                this.memory[this.I + i] = this.V[i];
                            }
                            this.I += x + 1;
                            break;
                        case 0x65: // LD Vx, [I]
                            for (let i = 0; i <= x; i++) {
                                this.V[i] = this.memory[this.I + i];
                            }
                            this.I += x + 1;
                            break;
                    }
                    break;

                default:
                    console.warn('Unknown opcode: 0x' + opcode.toString(16).padStart(4, '0'));
            }
        }
