    // Canvas setup
    const canvas = document.getElementById('display');
    const ctx = canvas.getContext('2d');

    // Scale display
    const SCALE = 10;
    canvas.style.width = (64 * SCALE) + 'px';
    canvas.style.height = (32 * SCALE) + 'px';

    // Create image data
    const imageData = ctx.createImageData(64, 32);

    // Emulator instance
    let chip8 = new Chip8();
    chip8.loadROM(demoROM);

    // State
    let running = false;
    let instructionsPerFrame = 10;
    let lastFrameTime = 0;

    // DOM elements
    const runBtn = document.getElementById('runBtn');
    const speedSlider = document.getElementById('speedSlider');
    const speedValue = document.getElementById('speedValue');

    // Update speed display
    function updateSpeed() {
        instructionsPerFrame = parseInt(speedSlider.value);
        speedValue.textContent = instructionsPerFrame;
    }

    // Toggle run/pause
    function toggleRun() {
        running = !running;
        runBtn.textContent = running ? 'Pause' : 'Run';
        runBtn.style.background = running ? '#4CAF50' : '#3a3a3a';
        runBtn.style.color = running ? '#000' : '#e0e0e0';
    }

    // Single step
    function singleStep() {
        running = false;
        runBtn.textContent = 'Run';
        runBtn.style.background = '#3a3a3a';
        runBtn.style.color = '#e0e0e0';
        chip8.step();
        render();
        updateDebugger();
    }

    // Reset emulator
    function resetEmulator() {
        running = false;
        runBtn.textContent = 'Run';
        runBtn.style.background = '#3a3a3a';
        runBtn.style.color = '#e0e0e0';
        chip8.reset();
        render();
        updateDebugger();
    }

    // Load ROM from file
    function loadROM(event) {
        const file = event.target.files[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = function(e) {
            const bytes = new Uint8Array(e.target.result);
            chip8.loadROM(bytes);
            running = false;
            runBtn.textContent = 'Run';
            runBtn.style.background = '#3a3a3a';
            runBtn.style.color = '#e0e0e0';
            render();
            updateDebugger();
        };
        reader.readAsArrayBuffer(file);
    }

    // Render display
    function render() {
        const data = imageData.data;

        for (let y = 0; y < 32; y++) {
            for (let x = 0; x < 64; x++) {
                const idx = y * 64 + x;
                const pixel = chip8.display[idx];
                const pixelIdx = idx * 4;

                if (pixel === 1) {
                    data[pixelIdx] = 76;     // R
                    data[pixelIdx + 1] = 175; // G
                    data[pixelIdx + 2] = 80;  // B
                    data[pixelIdx + 3] = 255; // A
                } else {
                    data[pixelIdx] = 0;
                    data[pixelIdx + 1] = 0;
                    data[pixelIdx + 2] = 0;
                    data[pixelIdx + 3] = 255;
                }
            }
        }

        ctx.putImageData(imageData, 0, 0);
    }

    // Update debugger panel
    function updateDebugger() {
        document.getElementById('debugOp').textContent = '0x' + chip8.debugOpcode.toString(16).padStart(4, '0');
        document.getElementById('debugPC').textContent = '0x' + chip8.PC.toString(16).padStart(4, '0');
        document.getElementById('debugI').textContent = '0x' + chip8.I.toString(4).padStart(4, '0');

        // Stack
        let stackStr = '--';
        if (chip8.SP > 0) {
            stackStr = chip8.stack.slice(0, chip8.SP).map(s => '0x' + s.toString(16).padStart(4, '0')).join(', ');
        }
        document.getElementById('debugStack').textContent = stackStr;

        // Timers
        document.getElementById('debugDelay').textContent = chip8.delayTimer;
        document.getElementById('debugSound').textContent = chip8.soundTimer;

        // Registers
        for (let i = 0; i < 16; i++) {
            document.getElementById('debugV' + i).textContent = '0x' + chip8.V[i].toString(16).padStart(2, '0');
        }
    }

